 paused=false;
 private pivot?:Body;private ballBoundary?:Body;private flags=new Set<string>();private platforms:Platform[]=[];private originals:Body[]=[];private balls:Ball[]=[];private start=0;private nextBall=0;private ballCycle=-1;private deferredSpawn=false;
 constructor(private sim:Simulation){}
 configure(ids:readonly string[]){const next=new Set(ids.filter(x=>['windy_weather','bouncy_bombardment','crumble_time','tilt_a_frog'].includes(x)));if([...next].sort().join() === [...this.flags].sort().join())return;const retained=this.flags.has('bouncy_bombardment')&&next.has('bouncy_bombardment')?this.capture()?.balls??[]:[];const nextId=this.nextBall;this.dispose();this.flags=next;this.start=this.sim.tick;if(next.has('crumble_time')||next.has('tilt_a_frog'))this.build();if(next.has('bouncy_bombardment')){this.ballBoundary=this.sim.world.createBody(Vec2(WIDTH/2,HEIGHT+1));this.ballBoundary.setUserData({chaosBallBoundary:true});this.ballBoundary.createFixture(Box(WIDTH/2, .25),{filterCategoryBits:8,filterMaskBits:4,restitution:1,friction:0});this.restoreBalls(retained,true);this.nextBall=nextId;}}
 private build(){const s=this.sim,solids=getArena(simulationArena(s)).solids;for(let b=s.world.getBodyList();b;b=b.getNext())if(!s.frogs.some(f=>f.body===b)&&!(b.getUserData()as any)?.chaosBall)this.originals.push(b);if(this.flags.has('tilt_a_frog'))this.pivot=s.world.createBody();
