   const count=source===0?Math.ceil(r.w/ARENA_CHAOS.sectionWidth):1;for(let section=0;section<count;section++){const solid:Solid=count===1?{...r,...(r.outline?{outline:r.outline.map(p=>[...p] as[number,number])}:{})}:{...r,x:r.x-r.w/2+(section+.5)*r.w/count,w:r.w/count};const body=s.world.createBody({position:Vec2(solid.x,solid.y),type:this.flags.has('tilt_a_frog')?'dynamic':'static',angularDamping:ARENA_CHAOS.tiltDamping,bullet:true});body.setUserData({surface:r.surface,chaosPlatform:true});body.createFixture(solid.outline?Polygon(solid.outline.map(([x,y])=>Vec2(x,y))):Box(solid.w/2,solid.h/2),{friction:s.tuning.friction});if(this.pivot){body.setMassData({mass:ARENA_CHAOS.tiltMass,center:Vec2(0,0),I:ARENA_CHAOS.tiltMass*(solid.w**2+solid.h**2)/12});s.world.createJoint(new RevoluteJoint({bodyA:this.pivot,bodyB:body,localAnchorA:Vec2(solid.x,solid.y),localAnchorB:Vec2(0,0),enableLimit:false}));}this.platforms.push({id:this.platforms.length,source,solid,body,angle:0,velocity:0,stage:'solid',clock:0,load:0});}
