 private load(p:Platform){let weight=0;for(const f of this.sim.frogs){for(let e=f.body.getContactList();e;e=e.next){const c=e.contact;if(!c.isTouching()||!c.isEnabled())continue;const a=c.getFixtureA().getBody(),b=c.getFixtureB().getBody();if(a!==p.body&&b!==p.body)continue;const n=c.getWorldManifold(null)?.normal;if(!n||(a===f.body?n.y:-n.y)<.5)continue;weight+=f.body.getMass()*Math.max(-1,Math.min(1,(f.body.getPosition().x-p.solid.x)/(p.solid.w/2)));p.load++;break;}}return weight;}
 before(){if(!this.flags.size)return;if(this.paused){this.start++;for(const b of this.balls)b.body.setActive(false);return;}for(const b of this.balls)b.body.setActive(true);const s=this.sim,a=ARENA_CHAOS;for(const p of this.platforms){p.load=0;this.load(p);if(this.flags.has('crumble_time')){if(p.stage==='solid'){p.clock=p.load?p.clock+1:Math.max(0,p.clock-2);if(p.load){p.stage='cracking';p.clock=a.crumbleLoad;}}else if(p.stage==='cracking'){if(--p.clock<=0){for(const f of s.frogs)if(f.tongue?.target===p.body)s.detach(f);p.body.setActive(false);p.stage='absent';p.clock=a.crumbleAbsent;}}else if(p.stage==='absent'){if(--p.clock<=0){p.stage='returning';p.clock=a.crumbleReturnWarning;}}else if(p.clock>0)p.clock--;else if(!this.occupied(p)){p.body.setActive(true);p.stage='solid';p.clock=0;}}
   if(this.flags.has('tilt_a_frog'))p.body.setAngularVelocity(Math.max(-a.tiltSpeed,Math.min(a.tiltSpeed,p.body.getAngularVelocity())));
  }
  const wind=this.wind();if(this.flags.has('windy_weather')&&wind.stage==='gust')for(const f of s.frogs){if(!f.body.isDynamic()||s.grounded(f))continue;const v=f.body.getLinearVelocity().x,dv=Math.min(a.windAcceleration*DT,Math.max(0,a.windSpeedLimit-wind.direction*v));f.body.applyLinearImpulse(Vec2(wind.direction*dv*f.body.getMass(),0),f.body.getWorldCenter(),true);}
